import{_ as a,a as l,b as t,c as r,d as s,e as o}from"./chunks/da0cfa1fe3616fd5808e.Dg-lst_w.js";import{_ as n,C as h,o as u,c as d,j as e,a as c,E as m,a6 as b}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"重温一人企业（把自己变成一家企业）","description":"","frontmatter":{"title":"重温一人企业（把自己变成一家企业）","originalTitle":"The One-Person Business Revisited (Turn Yourself Into A Business)","date":"2023-06-16","originalUrl":"https://thedankoe.com/letters/the-one-person-business-revisited-turn-yourself-into-a-business/","minutes":13,"sourceHash":"ee2f4d929ae2f011137d8c6ea7203c543972257d52803b0667ef034ca7262333","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-one-person-business-revisited-turn-yourself-into-a-business/"}]]},"headers":[],"relativePath":"letters/the-one-person-business-revisited-turn-yourself-into-a-business.md","filePath":"letters/the-one-person-business-revisited-turn-yourself-into-a-business.md"}'),f={name:"letters/the-one-person-business-revisited-turn-yourself-into-a-business.md"};function _(k,p,q,g,P,x){const i=h("ArticleMeta");return u(),d("div",null,[p[0]||(p[0]=e("h1",{id:"重温一人企业-把自己变成一家企业",tabindex:"-1"},[c("重温一人企业（把自己变成一家企业） "),e("a",{class:"header-anchor",href:"#重温一人企业-把自己变成一家企业","aria-label":'Permalink to "重温一人企业（把自己变成一家企业）"'},"​")],-1)),m(i),p[1]||(p[1]=b('<p><a href="https://www.youtube.com/embed/QoBCtcWO02g?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+a+'" alt=""></p><p>一个新的社会已经出现。</p><p>一个虚拟的社会。</p><p>我们都以为“虚拟现实”距离真正存在还有几年时间，而且它将由苹果新款VR头显之类的技术组成。</p><p>但进化不是这样运作的。</p><p>进化是为了解决那些导致我们痛苦的问题。</p><p>这是一个缓慢发酵的过程。</p><p>而这个新社会的出现却像星辰爆炸一样迅速。我们称之为社交媒体。</p><p>人类生活中存在着亟待解决的问题，这促使程序员、有远见的人和商人构建了一个大众化的解决方案。</p><p>沟通曾是本地化的。</p><p>信息曾是本地化的。</p><p>商业曾是本地化的。</p><p>机会曾是本地化的。</p><p>几个世纪以来的地理限制在眨眼间被打破。</p><p>互联网促成了社交媒体的出现。</p><p>社交媒体促成了创作者经济的出现。</p><p>创作者经济推动了去中心化的发展。</p><p>工业革命导致了统治者层级结构不可持续的发展——顶层人少且权力更大，底层人多却权力更小。</p><p>随着创作者自我实现（creator actualization）层级结构的发展，信息时代开始逆转这一效应。</p><p>创作者通过内容和课程来教育、娱乐并激励阶梯在他们下方的人——但没有任何东西能阻碍任何个体晋升到阶梯的顶端。</p><p>让我们稍微拆解一下：</p><h3 id="什么是创作者社会" tabindex="-1">什么是创作者社会？ <a class="header-anchor" href="#什么是创作者社会" aria-label="Permalink to &quot;什么是创作者社会？&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>随着互联网的发展，信息的传播已经无法估量。</p><p>这带来了一个更先进、更全球化、更易于触达的社会的发展。</p><p>社会由各种机构，以及拥有共同信仰和文化理念的社区组成。</p><p>其中最显著的部分是学校系统、劳动力、社交和商业部落，以及宗教机构。</p><p>社交媒体扩展并瓦解了这些事物之间的界限。</p><p>一切正变得更加整体和相互连接，就像雨水汇入海洋一样，正如宇宙分裂与统一的模式所暗示的那样。</p><p>公立学校系统过去存在很多问题：</p><ul><li>趋同思维</li><li>割裂式学习</li><li>顺从而非真实</li><li>死记硬背而非注重过程</li><li>将失败视为必须避免的事</li><li>权威不可质疑</li><li>追求工作时长而非效率和真实价值</li><li>用书本知识来定义智力</li><li>十年不变的课程大纲，只操心把你训练成一个可被随时替换的打工人</li></ul><p>创作者社会中的新学校系统允许个体：</p><ul><li>追随自己的好奇心</li><li>找到最适合自己学习的老师（创作者）</li><li>将学习视为生活的一部分，而不是一项恼人的义务</li><li>学习现代技能，让你能快速适应瞬息万变的环境</li><li>寻找特定的知识，以助力追求自我产生（而非被分配）的目标</li><li>将创业放在首位，因为对于那些渴望从生活中获得更多的人来说，这是唯一合乎逻辑的终极目标</li></ul><p>新的学校系统就是互联网内容。这一切都没有被贴上标签。它只是虚拟生活的一部分。</p><p>宗教机构曾使信徒的思想变得狭隘，并抗击任何与他们相左的观点。</p><p>现在，在大多数创作者品牌中，你都可以接触到灵性觉知和教育。</p><p>你可以敞开心扉，研究不同的观点，并进行自我实验，直到培养出适合自己的哲学。</p><p>这不仅适用于灵性成长，也适用于心智、财务和健康方面。</p><h3 id="什么是创作者经济" tabindex="-1">什么是创作者经济？ <a class="header-anchor" href="#什么是创作者经济" aria-label="Permalink to &quot;什么是创作者经济？&quot;">​</a></h3><p>自从人类互动开始以来，商品的交换就一直是社会的自然组成部分。</p><p>价值创造和交换是沟通和人际关系的基础。人类是深度的社交动物。</p><p>金钱或货币，是一种中性的价值形式。</p><p>人们把它花在自己认为有价值的东西上。</p><p>他们认为有价值的东西取决于他们的身份、视角、目标、当前的心境，以及对自身问题的认知水平。</p><p>我们开始能看出营销和销售的重要性了——因为它们是展现你能提供何种价值的主要技能。</p><p>营销和销售会将上述所有因素考虑在内。</p><p>如果你不把产品或服务定位给一个有着特定目标（这暗示着某个特定问题）的特定人群（身份），你就赚不到钱。</p><p>创作者经济由以内容和产品形式分发价值的个体组成。</p><p>他们就那些有助于受众实现目标的技能和兴趣，对受众进行教育。</p><p>他们的产品或服务旨在产生结果，并让受众更快地向这些目标迈进。</p><h2 id="我的一人企业哲学" tabindex="-1">我的一人企业哲学 <a class="header-anchor" href="#我的一人企业哲学" aria-label="Permalink to &quot;我的一人企业哲学&quot;">​</a></h2><blockquote><p>世界上大约有70亿人。我希望有一天，能有差不多70亿家公司。——Naval</p></blockquote><p>最好的企业会改变人生。</p><p>而这种蜕变造就了成功的产品。</p><p>别再试图去解决想象出来的麻烦。</p><p>解决你自己的问题。</p><p>改变你自己的生活。</p><p>把你的方法打包起来。</p><p>给它贴上一个价格标签。</p><p>如果你解决的是真实的、有意义的问题，你失败的可能性就会降低。</p><p>这就是大多数刚踏入商业领域的人所面临的问题。</p><p>他们对营销、销售、心理学，乃至广义上的进化毫无了解。</p><p>当大多数人都在遭受低意识问题的折磨（这些问题正阻碍着集体自我走向开悟）时，别再妄想登陆土星或者建立价值十亿美元的科技公司了。</p><p>作为一个帮助人们解决生活中<em>实际</em>问题的<a href="/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge">微型教育企业</a>起步。</p><p><em>这</em>才是你为人类的幸福和进化做出贡献的方式。</p><p>你通过理解这些永恒的市场来做到这一点：健康、财富、人际关系和幸福。</p><p>通过解决你自己在这几个领域中的问题，你可以：</p><ul><li>推动自身的自我实现</li><li>用你自己的故事创造一份可以传承下去的独特地图</li><li>通过帮助他人疗愈和实现目标来赚取收入</li></ul><p>从那里开始，每个人都处于一种更高的意识状态。</p><p>然后我们就可以把时间花在自己热爱的事情上，去解决我们充满热情的更深层次的问题（比如登陆土星）。</p><h2 id="自我变现之路" tabindex="-1">自我变现之路 <a class="header-anchor" href="#自我变现之路" aria-label="Permalink to &quot;自我变现之路&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>社交媒体是一个新社会。</p><p>个人品牌就是这个社会中的“人”。</p><p>而且，这并不局限于拥有企业的人。</p><p>大小创作者们都在四处招兵买马。</p><p>品牌和企业都在雇佣那些能在公开场合展现自身价值的人。</p><p>社交媒体是一个公共求职板、公共学校、公共笔记系统，也是一场公共派对，你可以在这里结交朋友，培养商业关系。</p><p>一开始，你可以为另一个创作者工作，以此在这个新社会中积累经验。这是一个很好的选择，但你也可以直接开始打造你自己的事业。</p><h3 id="路径一-学习一项技能-出售一项技能" tabindex="-1">路径一：学习一项技能，出售一项技能 <a class="header-anchor" href="#路径一-学习一项技能-出售一项技能" aria-label="Permalink to &quot;路径一：学习一项技能，出售一项技能&quot;">​</a></h3><p>这是大多数人建议你快速开始赚钱的做法：</p><ul><li>学习一项创作者或品牌在业务中使用的现代技能（例如邮件营销、漏斗设计或内容写作）</li><li>围绕该技能创作内容来展示你的知识（坦白说，这不会吸引多少粉丝。你的个人主页会更像是一份简历）。</li><li>为自由职业或咨询服务收取更高的价格，因为你没有足够的受众让你能在睡梦中把产品卖出去。</li></ul><p>要想让这一切奏效，你必须<a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">学习长青技能</a>：写作、演讲、营销和销售。</p><h3 id="路径二-成为围绕你兴趣的价值创作者" tabindex="-1">路径二：成为围绕你兴趣的价值创作者 <a class="header-anchor" href="#路径二-成为围绕你兴趣的价值创作者" aria-label="Permalink to &quot;路径二：成为围绕你兴趣的价值创作者&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>这很难说明白，因为最常见的问题是：“我没有任何兴趣。”</p><p>所以，让我们从这里开始。</p><p>你可以通过向某个目标投入精力来培养对某一话题的兴趣。</p><p>这样一来，如果你没有实现目标，你就会觉得白白浪费了你的投资。这种压力会促使你对自己负责。</p><p>真正的目标基于追求自我实现的永恒市场。</p><p>你在此过程中了解到的兴趣，都会被应用到该目标的实现上。</p><p>对于健康市场，我可能会对营养、训练和心理健康的细分子话题产生兴趣：</p><ul><li>健美</li><li>原始人饮食法</li><li>极简训练</li><li>瑜伽</li><li>正念</li></ul><p>对于财富市场，我可能会对商业、职业发展和金融的细分子话题产生兴趣：</p><ul><li>自由职业</li><li>软件即服务 (SaaS)</li><li>简历制作</li><li>面试准备</li><li>预算规划</li><li>前文列出的任何技能</li></ul><p>对于人际关系市场，我可能会对社交动态、约会和婚姻的细分子话题产生兴趣：</p><ul><li>伴侣心理治疗</li><li>自信与个人魅力</li><li>日间搭讪</li><li>如何上前搭讪</li></ul><p>所有这些都能帮我推动每个领域的发展。这就是你成为现代“文艺复兴式全才”的方式。</p><p>如果你想真正做到不可替代，你就必须成为一名终身的自学者（autodidact）。</p><p>在这个新社会中，得益于互联网内容、课程以及非传统的教育方式，你可以用创纪录的速度学会任何东西。</p><h3 id="路径三-双管齐下以获得最大成效" tabindex="-1">路径三：双管齐下以获得最大成效 <a class="header-anchor" href="#路径三-双管齐下以获得最大成效" aria-label="Permalink to &quot;路径三：双管齐下以获得最大成效&quot;">​</a></h3><p>有了个人品牌，为了让它取得成功，你将被迫学习绝大多数现代技能。</p><p>你必须构建自己的着陆页、漏斗、邮件、内容、主页设计、视觉图形以及其他所有东西，才能让你的品牌获得成功。</p><p>如果它无助于你的品牌增长，它也就帮不了别人，在这种情况下就不值得去学。</p><p>当你的自有品牌取得成果时，你也就具备了帮助他人发展品牌的知识。</p><p>你将要销售的产品或服务（用来实践你的技能发展）将基于你的兴趣。</p><p>你将围绕这些兴趣，通过自由职业或咨询服务创造一个最小可行性报价。</p><p>随着你用产出的内容不断扩大受众群，你最终可以将其转化为更不费吹灰之力就能卖出去的产品。</p><p>这是一条更长的路，但真的非常值得。</p><p>你极大地提升了自己，并且你的企业拥有比市面上大多数企业更多的杠杆。</p><h2 id="_6位数一人企业的四大支柱" tabindex="-1">6位数一人企业的四大支柱 <a class="header-anchor" href="#_6位数一人企业的四大支柱" aria-label="Permalink to &quot;6位数一人企业的四大支柱&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>一人企业的商业模式可以有许多种定义。</p><p>既然我现在有了一个小团队，我就不能真把自己称为“一人企业”了，但我打算重新定义它，好让我还能这么叫（哈哈）。</p><p>除此之外，我在自己并不在乎的商业模式上走得有点太远了。我正积极地试图恢复到只有我一个人，也许外加一名虚拟助理（VA）的状态。我能接受随之而来的收入减少。</p><p>我已经意识到我想要的是什么（写作和创意挑战），这让我能够（随着时间的推移）无情地淘汰那些挡道的东西。</p><p>一人企业模式就是<em>把你自己变成一家企业。</em></p><p>这是一种新颖且引人注目的说法，意思是：“<em>变得高价值，展现你自己，直到足够多的人知道你是谁、你做什么以及你为什么这样做。机会将会产生复利。</em>”</p><p>简而言之，这就是你要获得成功真正需要做的一切。</p><p>为了更清楚起见，让我们深入探讨一人企业的4个支柱：</p><p><img src="'+o+'" alt=""></p><h3 id="品牌——你就是细分领域" tabindex="-1">品牌——你就是细分领域 <a class="header-anchor" href="#品牌——你就是细分领域" aria-label="Permalink to &quot;品牌——你就是细分领域&quot;">​</a></h3><p>你的个人品牌是你在新社会中的“自我”或“身份”。</p><p>你的身份是塑造你视角的底层故事。</p><p>你的视角包含着你用来感知情况的目标。</p><p>这些目标可以是别人分配给你的（社会化条件反射），也可以是自我产生的（与你的愿景保持一致）。</p><p>当你读一本书时，你的理解会和旁人不同，因为你们把不同的目标当作了自己的滤镜。</p><p>如果我在人生财务低谷期读《觉知》（<em>Awareness</em>）这本书，我会吸收与实现我的财务愿景相关的想法（我也能把这些写进我的内容里发布出去）。</p><p>另一个人如果在人生感情顺遂期读这本书，他们可能什么也得不到，或者会吸收有助于培养这段感情的想法。</p><p>你的品牌就是你对未来的愿景（并且你的愿景会随着你的成长而进化）。</p><p>你对未来的愿景意味着你拥有，或者正在学习实现它所必需的技能和兴趣。</p><p>你的工作就是在任何读者能接触到你的地方阐明这一点。你所有的内容都将通过你的品牌视角来编写。</p><p>如果我当前的愿景/目标/目的是赚更多的钱……</p><p>而我已经学会或正在学习的技能是营销、健康和灵性……</p><p>我的个人简介就会是：“我撰写关于营销、健康和灵性的内容，这样你就能建立一个全面发展的一人企业。”</p><p>是的，即使是健康和灵性也可以被包装成助力商业的一种方式。这正是大多数人感到困惑的地方，他们不知道如何将自己的兴趣融入到一个感觉被束缚的受限细分领域中。</p><p>你在引导人们走向哪里？</p><p>这就是你吸引粉丝的方式。</p><h3 id="内容——记录你的想法" tabindex="-1">内容——记录你的想法 <a class="header-anchor" href="#内容——记录你的想法" aria-label="Permalink to &quot;内容——记录你的想法&quot;">​</a></h3><p>我喜欢把社交媒体看作一个公开的笔记系统，你在上面记录：</p><ul><li>你在学什么，以及它如何应用到你的生活中</li><li>你对自己的技能和兴趣的想法和观点</li><li>你在整个人生故事中学到的教训</li></ul><p>不知不觉中，我们正在互联网上以一种可探索的方式积极构建集体意识。</p><p>但是，你不能只是把事情写下来，然后祈祷你的品牌会成长。</p><p>你必须研究营销和说服力，让自己沉浸在表现优异的内容中，这样你才能注意到它们之间的共同模式。</p><p>我推荐<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>落地页上的免费课程——你只需在页面顶部输入你的电子邮件即可。</p><p>如果你还没有学习过营销、销售或文案写作——现在就开始吧。它们会改变你的生活。由于在这封信中要讲的内容太多了（更何况我以前已经多次谈论过它们，<a href="/letters/value-creation-the-skill-that-built-my-one-person-business">这封信是一个很好的起点</a>）。</p><h3 id="产品——公开的个人项目" tabindex="-1">产品——公开的个人项目 <a class="header-anchor" href="#产品——公开的个人项目" aria-label="Permalink to &quot;产品——公开的个人项目&quot;">​</a></h3><p>在一人企业的理念下，你通过解决自己的问题并出售解决方案来为新社会做贡献。</p><p>发展过程如下：</p><ul><li>找出你生活中的一个问题</li><li>把它变成一个获取经验的个人项目</li><li>把它变成一个最小可行性报价方案</li><li>开始以500-1000美元的价格出售（自由职业或咨询）</li><li>在此过程中通过内容建立你的受众</li><li>增加你报价方案的深度和复杂性</li><li>当你觉得准备好时，将其产品化，这样你睡觉时也能赚钱</li></ul><p>这需要1到3年的时间。</p><p>如果你的目标是在商业或事业中赚更多的钱，你可以学习像邮件营销这样的技能。</p><p>如果你的目标是练出肌肉，增加自己的吸引力和自信心，你可以去健身房并调整你的营养搭配。</p><p>一旦你做到了，你就可以开始把它作为自由职业或咨询服务来出售。</p><p>以邮件营销为例，自由职业是显而易见的选择。</p><p><em>教导</em>他人这一选项往往会被人忽视。</p><p>你可以把你追求邮件营销时学到的知识教给其他创作者或品牌——尤其<em>当你已经把它应用到自己的品牌中并在过程中看到了成果的话</em><em>。</em></p><p>“项目”在这里是如何发挥作用的？</p><p>项目是你真正在现实世界中解决问题的方式。</p><p>它们迫使你应用所学的知识。</p><p>它们也是有形的，是你的成果。</p><p>你可以对它们进行迭代，让它们随着时间的推移变得更好。</p><p>你可以反思它们，让下一个人更容易实现目标。</p><p>关于邮件营销，你可以为你自己的品牌写一个邮件序列。你可以练习销售别人的产品（分销），或者练习推广你最喜欢的书或产品。围绕它们设计出一套有说服力的论点。</p><p>然后，为你最喜欢的品牌做同样的事情。为他们建立一个邮件序列。</p><p>既然你有了真实的实践经验，你就可以向那个品牌推销你的服务，或者开始帮助其他人建立他们自己的序列。</p><p>教导他人是你发现知识盲区的方式。</p><p>这是你能够填补它们的唯一途径。</p><p>如果不建立项目，也不去教导你所学的知识，你的旅程将会缓慢而痛苦。</p><h3 id="营销——向你自己推销" tabindex="-1">营销——向你自己推销 <a class="header-anchor" href="#营销——向你自己推销" aria-label="Permalink to &quot;营销——向你自己推销&quot;">​</a></h3><p>如果你从不推销自己，你连一分钱都赚不到。</p><p>就这么简单。</p><p>人们（在压力大、不堪重负和恐慌的状态下）问我，为什么他们的努力赚不到钱。</p><p>那是因为除了推销自己的产品或服务，他们什么都做。</p><p>营销存在于你品牌的方方面面，但最主要体现在：</p><ul><li>你产品和服务的落地页</li><li>你推销它们的邮件</li><li>你推销它们的内容</li><li>你用来评估别人是否适合它们的触达信息</li></ul><p>同样，我以前谈论过所有这些，并在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>中给出了我确切的系统，所以让我们来看一个你可以用来练习的框架。</p><p><strong>明确他们的目标或渴望的结果</strong></p><p>你必须知道你的受众想要什么。</p><p>通过在你的营销中询问他们或向他们阐明目标是什么，让这成为最首要的事。</p><p>当你自身就是细分领域时，这就是一个你已经实现了的目标。你早就应该通过自我反思知道受众渴望什么了。</p><p><strong>找出阻碍他们的因素</strong></p><p>人们未能实现目标的原因是什么？</p><p>你一开始没有实现目标的原因是什么？</p><p>在你的推广中把它写出来，或者在你的触达信息中问你正在交谈的人。</p><p>“是什么阻碍了你实现[他们提到的目标]？”</p><h3 id="提出你的解决方案来解决火烧眉毛的问题" tabindex="-1">提出你的解决方案来解决火烧眉毛的问题 <a class="header-anchor" href="#提出你的解决方案来解决火烧眉毛的问题" aria-label="Permalink to &quot;提出你的解决方案来解决火烧眉毛的问题&quot;">​</a></h3><p>既然他们清楚了目标和阻碍因素，你也就知道了他们是否适合你的解决方案。</p><p>如果不适合，祝他们愉快，然后不要去打扰他们。</p><p>如果适合，问问他们如果实现了那个目标，他们的生活会受到什么影响——这能让他们直面自己正在面临的问题。</p><p>从这里开始，你就可以抛出你的报价方案作为潜在的解决方案了。</p><p>如果你是初学者，想深入练习这个过程，请阅读关于<a href="/letters/how-to-network-with-millionaires-and-build-a-name-for-yourself">无需求感社交网络过程</a>的这封信。</p><p>到目前为止，这就是你需要了解的关于一人企业模式的全部内容。</p><p>欢迎在我的YouTube频道上观看<a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4" target="_blank" rel="noreferrer">一人企业播放列表</a>的其余内容。</p><p>祝你今天过得愉快。</p><p>——丹·柯（Dan Koe）</p><hr><p><a href="/en/letters/the-one-person-business-revisited-turn-yourself-into-a-business">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',199))])}const w=n(f,[["render",_]]);export{T as __pageData,w as default};
